#!/usr/bin/env python3
"""本地对话命令行程序：校验对话 JSON 结构，并进行一次分支预览、只读节点查看或入向引用查询。

用法：
    python dialogue.py validate <文件路径>
    python dialogue.py preview <文件路径> --choice <选项编号> [--node <节点编号>]
    python dialogue.py inspect <文件路径> [--node <节点编号>]
    python dialogue.py references <文件路径> [--node <节点编号>]

preview 省略 --node 时从 start 出发；--choice 与 --node 两对参数顺序可互换。
inspect 省略 --node 时查看 start 指定的节点，只输出该节点信息，不选择选项。
references 省略 --node 时查询 start 指定的节点，列出直接指向该节点的选项。
仅使用 Python 3 标准库，无需网络、外部账号或额外依赖。
"""

import json
import sys

USAGE = (
    "用法：\n"
    "  python dialogue.py validate <文件路径>\n"
    "  python dialogue.py preview <文件路径> --choice <选项编号> "
    "[--node <节点编号>]"
)

# inspect 参数错误专用的用法说明；validate/preview 的用法输出保持原样。
INSPECT_USAGE = USAGE + (
    "\n  python dialogue.py inspect <文件路径> [--node <节点编号>]"
)

# references 参数错误专用的用法说明。
REFERENCES_USAGE = INSPECT_USAGE + (
    "\n  python dialogue.py references <文件路径> [--node <节点编号>]"
)


class DialogueError(Exception):
    """对话文件结构校验失败。"""


def fail(message):
    """向标准错误写一条说明并以退出码 2 结束，不输出调用栈。"""
    sys.stderr.write(message + "\n")
    sys.exit(2)


def is_id_string(value):
    """id、start、target 的要求：至少含一个非空白字符的字符串。"""
    return isinstance(value, str) and value.strip() != ""


def load_dialogue(path):
    """读取并解析 JSON 文件；文件类错误在此统一报告。"""
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except OSError as exc:
        detail = exc.strerror or str(exc)
        fail("无法读取文件 {}：{}".format(path, detail))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        fail("文件 {} 的 UTF-8 解码失败：{}".format(path, exc))
    try:
        return json.loads(text)
    except json.JSONDecodeError as exc:
        fail("文件 {} 存在 JSON 语法错误（第 {} 行第 {} 列）：{}".format(
            path, exc.lineno, exc.colno, exc.msg))


def validate_dialogue(data):
    """校验整份对话数据（含无法从起点到达的节点）。

    成功时返回 (start, nodes)；失败时抛出 DialogueError，
    说明中带 JSON 字段位置，如 nodes[1].id。
    """
    if not isinstance(data, dict):
        raise DialogueError("顶层 JSON 必须是对象")

    if "start" not in data:
        raise DialogueError("缺少字段 start")
    if not is_id_string(data["start"]):
        raise DialogueError("start 必须是至少含一个非空白字符的字符串")
    start = data["start"]

    if "nodes" not in data:
        raise DialogueError("缺少字段 nodes")
    nodes = data["nodes"]
    if not isinstance(nodes, list):
        raise DialogueError("nodes 必须是数组")
    if not nodes:
        raise DialogueError("nodes 必须是非空数组")

    # 第一遍：逐节点校验结构并收集编号，检查重复。
    id_locations = {}
    for i, node in enumerate(nodes):
        loc = "nodes[{}]".format(i)
        if not isinstance(node, dict):
            raise DialogueError("{} 必须是对象".format(loc))
        for field in ("id", "text", "options"):
            if field not in node:
                raise DialogueError("缺少字段 {}.{}".format(loc, field))
        if not is_id_string(node["id"]):
            raise DialogueError("{}.id 必须是至少含一个非空白字符的字符串".format(loc))
        node_id = node["id"]
        if node_id in id_locations:
            raise DialogueError("节点编号重复：{} 与 {}.id 同为 {!r}".format(
                id_locations[node_id], loc, node_id))
        id_locations[node_id] = loc + ".id"
        if not isinstance(node["text"], str):
            raise DialogueError("{}.text 必须是字符串".format(loc))
        options = node["options"]
        if not isinstance(options, list):
            raise DialogueError("{}.options 必须是数组".format(loc))
        for j, option in enumerate(options):
            oloc = "{}.options[{}]".format(loc, j)
            if not isinstance(option, dict):
                raise DialogueError("{} 必须是对象".format(oloc))
            for field in ("text", "target"):
                if field not in option:
                    raise DialogueError("缺少字段 {}.{}".format(oloc, field))
            if not isinstance(option["text"], str):
                raise DialogueError("{}.text 必须是字符串".format(oloc))
            if not is_id_string(option["target"]):
                raise DialogueError(
                    "{}.target 必须是至少含一个非空白字符的字符串".format(oloc))

    # 第二遍：校验 start 与所有 target 的引用（允许循环引用）。
    if start not in id_locations:
        raise DialogueError("start 引用了不存在的节点 {!r}".format(start))
    for i, node in enumerate(nodes):
        for j, option in enumerate(node["options"]):
            if option["target"] not in id_locations:
                raise DialogueError(
                    "nodes[{}].options[{}].target 引用了不存在的节点 {!r}".format(
                        i, j, option["target"]))

    return start, nodes


def find_node(nodes, node_id):
    for node in nodes:
        if node["id"] == node_id:
            return node
    return None  # 校验通过后不会发生


def cmd_validate(path):
    data = load_dialogue(path)
    try:
        validate_dialogue(data)
    except DialogueError as exc:
        fail("校验失败：{}".format(exc))
    sys.stdout.write("校验通过\n")
    return 0


def cmd_preview(path, choice_arg, node_arg=None):
    # 预览前先完成整份文件校验（未选中分支的结构或引用错误也在此暴露）。
    data = load_dialogue(path)
    try:
        start, nodes = validate_dialogue(data)
    except DialogueError as exc:
        fail("校验失败：{}".format(exc))

    # 省略 --node 时仍从 start 出发；节点编号按原字符串精确匹配。
    origin_id = start if node_arg is None else node_arg
    origin_node = find_node(nodes, origin_id)
    if origin_node is None:
        fail("文件中不存在编号为 {!r} 的节点".format(origin_id))
    options = origin_node["options"]

    try:
        choice = int(choice_arg)
    except ValueError:
        if node_arg is None:
            fail("--choice 的值 {!r} 无法解析为整数（起点编号为 {!r}）".format(
                choice_arg, origin_id))
        fail("--choice 的值 {!r} 无法解析为整数（出发节点编号为 {!r}）".format(
            choice_arg, origin_id))

    if not options:
        if node_arg is None:
            fail("--choice {} 无效：起点 {!r} 是结尾节点，没有有效选项".format(
                choice, origin_id))
        fail("--choice {} 无效：出发节点 {!r} 是结尾节点，没有有效选项".format(
            choice, origin_id))
    if not 1 <= choice <= len(options):
        if node_arg is None:
            fail("--choice {} 不在起点 {!r} 的有效选项编号范围 1 到 {} 内".format(
                choice, origin_id, len(options)))
        fail("--choice {} 不在出发节点 {!r} 的有效选项编号范围 1 到 {} 内".format(
            choice, origin_id, len(options)))

    # 选项编号从 1 开始，依据数组顺序确定；只输出目标节点文字，不前进、不改写文件。
    target_id = options[choice - 1]["target"]
    target_node = find_node(nodes, target_id)
    sys.stdout.write(target_node["text"] + "\n")
    return 0


def cmd_inspect(path, node_arg=None):
    # 查看前先完成整份文件校验（不可达节点的结构或引用错误也在此暴露）。
    data = load_dialogue(path)
    try:
        start, nodes = validate_dialogue(data)
    except DialogueError as exc:
        fail("校验失败：{}".format(exc))

    # 省略 --node 时查看 start 指定的节点；节点编号按原字符串精确匹配。
    origin_id = start if node_arg is None else node_arg
    origin_node = find_node(nodes, origin_id)
    if origin_node is None:
        fail("文件中不存在编号为 {!r} 的节点".format(origin_id))

    # 只读查看：不选择选项、不沿引用继续访问，也不保存当前节点或改写文件。
    result = {
        "id": origin_node["id"],
        "text": origin_node["text"],
        "options": [
            {"choice": i + 1, "text": option["text"], "target": option["target"]}
            for i, option in enumerate(origin_node["options"])
        ],
    }
    sys.stdout.write(json.dumps(result, ensure_ascii=False) + "\n")
    return 0


def cmd_references(path, node_arg=None):
    # 查询前先完成整份文件校验（不可达节点的结构或引用错误也在此暴露）。
    data = load_dialogue(path)
    try:
        start, nodes = validate_dialogue(data)
    except DialogueError as exc:
        fail("校验失败：{}".format(exc))

    # 省略 --node 时查询 start 指定的节点；节点编号按原字符串精确匹配。
    target_id = start if node_arg is None else node_arg
    if find_node(nodes, target_id) is None:
        fail("文件中不存在编号为 {!r} 的节点".format(target_id))

    # 只统计各节点 options 里的直接引用：覆盖整份文件（含不可达来源），
    # 逐项保留同一来源的多个选项，自引用照常计入；start 字段本身不算引用，
    # 也不沿循环关系展开间接引用。结果按 nodes 顺序及各自 options 顺序排列。
    references = []
    for node in nodes:
        for i, option in enumerate(node["options"]):
            if option["target"] == target_id:
                references.append({
                    "source": node["id"],
                    "choice": i + 1,
                    "text": option["text"],
                })
    result = {"id": target_id, "references": references}
    sys.stdout.write(json.dumps(result, ensure_ascii=False) + "\n")
    return 0


def parse_inspect_args(rest):
    """解析 inspect 可选的 --node 键值对（至多一次）。

    rest 形如 [] 或 ['--node', 'n']；任何多余、重复或缺值参数
    都按既有用法错误处理，并在读取文件前结束。
    """
    if not rest:
        return None
    if len(rest) == 2 and rest[0] == "--node":
        return rest[1]
    fail(INSPECT_USAGE)


def parse_references_args(rest):
    """解析 references 可选的 --node 键值对（至多一次）。

    rest 形如 [] 或 ['--node', 'n']；任何多余、重复、缺值或
    --node=编号 连写形式的参数都按用法错误处理，并在读取文件前结束。
    """
    if not rest:
        return None
    if len(rest) == 2 and rest[0] == "--node":
        return rest[1]
    fail(REFERENCES_USAGE)


def parse_preview_args(rest):
    """解析 preview 的 --choice/--node 键值对（顺序可互换、各至多一次）。

    rest 形如 ['--choice', '2', '--node', 'n']；任何多余、
    重复或缺值参数都按既有用法错误处理。
    """
    values = {}
    i = 0
    while i < len(rest):
        name = rest[i]
        if name not in ("--choice", "--node"):
            fail(USAGE)
        if name in values:
            fail(USAGE)
        if i + 1 >= len(rest):
            fail(USAGE)
        values[name] = rest[i + 1]
        i += 2
    if "--choice" not in values:
        fail(USAGE)
    return values["--choice"], values.get("--node")


def main(argv):
    if len(argv) < 2:
        fail(USAGE)
    command = argv[1]
    if command == "validate":
        if len(argv) != 3:
            fail(USAGE)
        return cmd_validate(argv[2])
    if command == "preview":
        if len(argv) < 5:
            fail(USAGE)
        choice_arg, node_arg = parse_preview_args(argv[3:])
        return cmd_preview(argv[2], choice_arg, node_arg)
    if command == "inspect":
        if len(argv) < 3:
            fail(INSPECT_USAGE)
        node_arg = parse_inspect_args(argv[3:])
        return cmd_inspect(argv[2], node_arg)
    if command == "references":
        if len(argv) < 3:
            fail(REFERENCES_USAGE)
        node_arg = parse_references_args(argv[3:])
        return cmd_references(argv[2], node_arg)
    fail(USAGE)


if __name__ == "__main__":
    sys.exit(main(sys.argv))

# -*- coding: utf-8 -*-
"""dialogue.py 入向引用查询（references）命令行回归测试。

以 sample.json 为基础派生临时副本，覆盖省略 --node 查询起点、
显式 --node 结果一致、结尾节点单条引用、不可达来源的多个选项逐项保留、
自引用计入、循环关系不展开间接引用、start 字段本身不算引用，
以及节点不存在、整份校验先于查询的失败边界。

运行方式（在项目目录下，仅需 Python 3 标准库，无需网络）：

    python -m unittest discover -v

验收依据：退出码、标准输出（按解析后的 JSON 对象核对，另核对结尾换行）、
标准错误，以及输入文件在执行前后字节不变。所有派生样例由测试独立写入
临时目录并自动清理，sample.json 保持原样，用例可重复运行且结果一致。
"""

import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

PROJECT_DIR = Path(__file__).resolve().parent
DIALOGUE = PROJECT_DIR / "dialogue.py"
SAMPLE = PROJECT_DIR / "sample.json"


def run_references(path, node=None):
    """以命令行方式执行 references；node 为 None 时省略 --node 参数。"""
    args = [sys.executable, str(DIALOGUE), "references", str(path)]
    if node is not None:
        args.extend(["--node", node])
    return subprocess.run(args, capture_output=True)


class ReferencesTestCase(unittest.TestCase):
    """公共断言：派生样例、文件字节不变、无调用栈、临时目录清理。"""

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.tmp_dir = Path(self._tmp.name)

    def load_sample_data(self):
        """深拷贝样例数据，派生用例之间互不影响。"""
        return json.loads(SAMPLE.read_text(encoding="utf-8"))

    def make_sample(self, data, name="case.json"):
        """把数据写成独立的临时 UTF-8 JSON 样例文件，返回路径。"""
        path = self.tmp_dir / name
        path.write_text(
            json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
        )
        return path

    def make_plain_sample(self, name="case.json"):
        """sample.json 的原样临时副本。"""
        return self.make_sample(self.load_sample_data(), name)

    def make_side_sample(self, name="case.json"):
        """在 sample.json 末尾追加不可达的 side 节点（甲、乙两个选项
        都指向 forest），返回临时副本路径。"""
        data = self.load_sample_data()
        data["nodes"].append(
            {
                "id": "side",
                "text": "岔路旁",
                "options": [
                    {"text": "甲", "target": "forest"},
                    {"text": "乙", "target": "forest"},
                ],
            }
        )
        return self.make_sample(data, name)

    def make_cycle_sample(self, name="case.json"):
        """构造 a、b 互相指向的循环对话，返回临时样例路径。"""
        data = {
            "start": "a",
            "nodes": [
                {
                    "id": "a",
                    "text": "甲地",
                    "options": [{"text": "去乙地", "target": "b"}],
                },
                {
                    "id": "b",
                    "text": "乙地",
                    "options": [{"text": "回甲地", "target": "a"}],
                },
            ],
        }
        return self.make_sample(data, name)

    def make_unused_sample(self, name="case.json"):
        """在 sample.json 末尾追加缺少 text 的不可达 unused 节点。"""
        data = self.load_sample_data()
        data["nodes"].append(
            {"id": "unused", "options": [{"text": "回到起点", "target": "start"}]}
        )
        return self.make_sample(data, name)

    def assert_file_unchanged(self, path, before):
        self.assertEqual(
            before,
            path.read_bytes(),
            "输入文件在执行后发生变化：{}".format(path),
        )

    def assert_no_traceback(self, stderr):
        self.assertNotIn("Traceback", stderr, "标准错误中不应出现调用栈")

    def run_and_assert_ok(self, path, expected_object, node=None):
        """成功路径：退出码 0、标准错误为空、输出为 JSON 对象加一个结尾换行。

        对象内容按解析后的 JSON 核对，不依赖键顺序或空格排版；
        结尾换行单独核对。
        """
        before = path.read_bytes()
        result = run_references(path, node=node)
        self.assert_file_unchanged(path, before)
        self.assertEqual(result.returncode, 0, "stderr: {!r}".format(result.stderr))
        self.assertEqual(result.stderr, b"", "成功时标准错误应为空")
        stdout = result.stdout.decode("utf-8")
        self.assertTrue(
            stdout.endswith("\n"), "标准输出应以一个结尾换行结束：{!r}".format(stdout)
        )
        self.assertNotIn(
            "\n", stdout[:-1], "结尾换行之前不应再有换行：{!r}".format(stdout)
        )
        actual = json.loads(stdout[:-1])
        self.assertEqual(
            actual,
            expected_object,
            "解析后的 JSON 对象应与预期完全一致",
        )
        return result

    def run_and_assert_fail(self, path, expected_parts, node=None):
        """失败路径：退出码 2、标准输出为空、标准错误包含各片段且无调用栈。"""
        before = path.read_bytes()
        result = run_references(path, node=node)
        self.assert_file_unchanged(path, before)
        self.assertEqual(result.returncode, 2, "失败时退出码应为 2")
        self.assertEqual(result.stdout, b"", "失败时标准输出应为空")
        stderr = result.stderr.decode("utf-8")
        self.assert_no_traceback(stderr)
        for part in expected_parts:
            self.assertIn(part, stderr, "标准错误应包含 {!r}".format(part))
        return result


class TestReferencesSuccess(ReferencesTestCase):
    """成功路径：省略 --node 查询起点，显式 --node 查询指定节点。"""

    def test_omitted_node_queries_start_with_empty_references(self):
        """省略 --node 时查询 start：start 字段本身不算选项引用，
        且 sample.json 中没有选项指向 start，结果为空数组。"""
        path = self.make_plain_sample()
        self.run_and_assert_ok(path, {"id": "start", "references": []})

    def test_explicit_start_matches_omitted_node(self):
        """显式 --node start 的结果应与省略 --node 完全一致。"""
        path = self.make_plain_sample()
        expected = {"id": "start", "references": []}
        explicit = self.run_and_assert_ok(path, expected, node="start")
        omitted = self.run_and_assert_ok(path, expected)
        self.assertEqual(explicit.stdout, omitted.stdout)
        self.assertEqual(explicit.stderr, omitted.stderr)
        self.assertEqual(explicit.returncode, omitted.returncode)

    def test_forest_has_single_reference_from_start(self):
        """查询结尾节点 forest：仅 start 的选项 1 指向它，文字为“向左走”。"""
        path = self.make_plain_sample()
        self.run_and_assert_ok(
            path,
            {
                "id": "forest",
                "references": [
                    {"source": "start", "choice": 1, "text": "向左走"},
                ],
            },
            node="forest",
        )

    def test_river_reference_uses_second_choice(self):
        """查询 river：start 的选项 2 指向它，choice 按来源 options 顺序编号。"""
        path = self.make_plain_sample()
        self.run_and_assert_ok(
            path,
            {
                "id": "river",
                "references": [
                    {"source": "start", "choice": 2, "text": "向右走"},
                ],
            },
            node="river",
        )

    def test_unreachable_source_options_kept_in_order(self):
        """追加不可达的 side 节点（甲、乙均指向 forest）：查询 forest 依次
        保留 start 的选项 1、side 的选项 1 和 2，文字与原选项一致。"""
        path = self.make_side_sample()
        self.run_and_assert_ok(
            path,
            {
                "id": "forest",
                "references": [
                    {"source": "start", "choice": 1, "text": "向左走"},
                    {"source": "side", "choice": 1, "text": "甲"},
                    {"source": "side", "choice": 2, "text": "乙"},
                ],
            },
            node="forest",
        )

    def test_self_reference_counts(self):
        """side 的唯一选项指向自身：查询 side 时该自引用正常计入。"""
        data = self.load_sample_data()
        data["nodes"].append(
            {
